/// Fast class: attitude [omega, q] and position [V, P], full precision.
struct Pose {
    static constexpr uint8_t kPort = 0x80;
    static constexpr bool kIsHeartbeat = false;
    static constexpr uint8_t kQos = 3; // telemetry (Control 0, Link 1, Event 2, Telemetry 3)
    static constexpr bool kLatest = true;
    static constexpr bool kAirEligible = false;
    static constexpr uint16_t kAirRateHz = 0;
    static constexpr uint16_t kUsbRateHz = 100;
    static constexpr size_t kMaxSize = 60;
    static constexpr size_t kMinSize = 56;

    uint32_t t_us = {}; // [us] 
    float omega[3] = {}; // [rad/s] body rates
    float q[4] = {}; // [w,x,y,z] body -> world
    float vel[3] = {}; // [m/s] NWU
    float pos[3] = {}; // [m] NWU from the reset reference
    float ground_distance = {}; // [m] downward lidar (VL53L0X) distance to the ground in metres, NaN if unavailable (the vehicle only reports a valid reading in its useful range 0.4 to 1.5 m). Missing (older sender) decodes as NaN

    /// Bytes written, 0 on failure (null buffer or too small).
    size_t encode(uint8_t* out, size_t cap) const {
        constexpr size_t total = 60;
        if (out == nullptr || cap < total) return 0;
        codec::put_u32(out + 0, t_us);
        for (size_t i = 0; i < 3; ++i) codec::put_f32(out + 4 + i * 4, omega[i]);
        for (size_t i = 0; i < 4; ++i) codec::put_f32(out + 16 + i * 4, q[i]);
        for (size_t i = 0; i < 3; ++i) codec::put_f32(out + 32 + i * 4, vel[i]);
        for (size_t i = 0; i < 3; ++i) codec::put_f32(out + 44 + i * 4, pos[i]);
        codec::put_f32(out + 56, ground_distance);
        return total;
    }

    /// False if the payload is shorter than kMinSize (or a tail is too long). Longer payloads are accepted (extra
    /// bytes ignored); optional fields missing from shorter payloads get their default/NaN.
    bool decode(const uint8_t* in, size_t len) {
        if (in == nullptr || len < kMinSize) return false;
        Pose t;
        t.t_us = codec::get_u32(in + 0);
        for (size_t i = 0; i < 3; ++i) t.omega[i] = codec::get_f32(in + 4 + i * 4);
        for (size_t i = 0; i < 4; ++i) t.q[i] = codec::get_f32(in + 16 + i * 4);
        for (size_t i = 0; i < 3; ++i) t.vel[i] = codec::get_f32(in + 32 + i * 4);
        for (size_t i = 0; i < 3; ++i) t.pos[i] = codec::get_f32(in + 44 + i * 4);
        if (len >= 60) {
            t.ground_distance = codec::get_f32(in + 56);
        } else {
            t.ground_distance = std::numeric_limits<float>::quiet_NaN();
        }
        *this = t;
        return true;
    }

    /// Calls v.scalar/array/chars/tail(name, member) for every field (used by tests and tooling).
    template <class V>
    void visit(V& v) {
        v.scalar("t_us", t_us);
        v.array("omega", omega);
        v.array("q", q);
        v.array("vel", vel);
        v.array("pos", pos);
        v.scalar("ground_distance", ground_distance);
        (void)v;
    }
};

/// Actuator outputs.
struct Actuators {
    static constexpr uint8_t kPort = 0x81;
    static constexpr bool kIsHeartbeat = false;
    static constexpr uint8_t kQos = 3; // telemetry (Control 0, Link 1, Event 2, Telemetry 3)
    static constexpr bool kLatest = true;
    static constexpr bool kAirEligible = false;
    static constexpr uint16_t kAirRateHz = 0;
    static constexpr uint16_t kUsbRateHz = 50;
    static constexpr size_t kMaxSize = 36;
    static constexpr size_t kMinSize = 32;

    uint32_t t_us = {}; // [us] 
    float flaps[4] = {}; // [rad] [TL, TR, BL, BR]; 0 = extended, increasing = folded toward the back
    float tvc[2] = {}; // [rad] thrust vector deflection [x, y]
    float thrust = {}; // [N] 
    float roll_torque = {}; // [N*m] TVC twist (roll) actuation as the roll torque about body Z the vanes produce (same meaning as AIR_ACTUATORS.roll_torque, unquantised). Missing (older sender) decodes as NaN = unknown

    /// Bytes written, 0 on failure (null buffer or too small).
    size_t encode(uint8_t* out, size_t cap) const {
        constexpr size_t total = 36;
        if (out == nullptr || cap < total) return 0;
        codec::put_u32(out + 0, t_us);
        for (size_t i = 0; i < 4; ++i) codec::put_f32(out + 4 + i * 4, flaps[i]);
        for (size_t i = 0; i < 2; ++i) codec::put_f32(out + 20 + i * 4, tvc[i]);
        codec::put_f32(out + 28, thrust);
        codec::put_f32(out + 32, roll_torque);
        return total;
    }

    /// False if the payload is shorter than kMinSize (or a tail is too long). Longer payloads are accepted (extra
    /// bytes ignored); optional fields missing from shorter payloads get their default/NaN.
    bool decode(const uint8_t* in, size_t len) {
        if (in == nullptr || len < kMinSize) return false;
        Actuators t;
        t.t_us = codec::get_u32(in + 0);
        for (size_t i = 0; i < 4; ++i) t.flaps[i] = codec::get_f32(in + 4 + i * 4);
        for (size_t i = 0; i < 2; ++i) t.tvc[i] = codec::get_f32(in + 20 + i * 4);
        t.thrust = codec::get_f32(in + 28);
        if (len >= 36) {
            t.roll_torque = codec::get_f32(in + 32);
        } else {
            t.roll_torque = std::numeric_limits<float>::quiet_NaN();
        }
        *this = t;
        return true;
    }

    /// Calls v.scalar/array/chars/tail(name, member) for every field (used by tests and tooling).
    template <class V>
    void visit(V& v) {
        v.scalar("t_us", t_us);
        v.array("flaps", flaps);
        v.array("tvc", tvc);
        v.scalar("thrust", thrust);
        v.scalar("roll_torque", roll_torque);
        (void)v;
    }
};

/// Mission setpoints and progress.
struct Mission {
    static constexpr uint8_t kPort = 0x82;
    static constexpr bool kIsHeartbeat = false;
    static constexpr uint8_t kQos = 3; // telemetry (Control 0, Link 1, Event 2, Telemetry 3)
    static constexpr bool kLatest = true;
    static constexpr bool kAirEligible = false;
    static constexpr uint16_t kAirRateHz = 0;
    static constexpr uint16_t kUsbRateHz = 20;
    static constexpr size_t kMaxSize = 64;
    static constexpr size_t kMinSize = 34;

    uint32_t t_us = {}; // [us] 
    float setpoint_pos[3] = {}; // [m] 
    float setpoint_vel[3] = {}; // [m/s] 
    float mission_time = {}; // [s] 
    uint8_t index = {};
    uint8_t phase = {};
    float setpoint_q[4] = {}; // attitude setpoint of the active attitude controller, [w,x,y,z] body -> world, NWU (as POSE.q). All four 0 = no attitude setpoint (no attitude controller active), otherwise a unit quaternion. NaN (missing, older sender) = unknown, treat as no setpoint
    uint8_t mission_mode = {}; // MissionMode of the active mission (Idle, Initialisation, Startup, Running, Finished), as AIR_MISSION.mission_mode and VEHICLE_STATUS.mission_mode. Missing (older sender) decodes as 0
    uint8_t waypoint = {}; // current waypoint index, 255 = the active mission is not the waypoint mission (as AIR_MISSION.waypoint). Missing (older sender) decodes as 0, so use mission_mode/VEHICLE_STATUS to know the sender is new
    float flip_start_altitude = {}; // [m] estimated altitude above the position reference (NWU up) at which the upright (flip) manoeuvre will begin, = the vehicle's getStopAltitude() = stopDist(Vz) + stop_altitude, re-estimated continuously. Sent only during the bellyflop freefall phase, otherwise NaN. Missing (older sender) = NaN
    float stop_altitude = {}; // [m] current value of the stop altitude parameter (altitude above the position reference where the vehicle ends up stopped, default 20 m, settable 5..60 m with the SetStopAltitude telecommand while on the ground). Always sent, the echo that confirms a setting. NaN = unknown / missing (older sender)
    float mission_elapsed = {}; // [s] seconds since the mission's T0 (mission begin) as the vehicle counts them: negative (T-minus) during the countdown, 0 at T0, continuous across all mission steps (unlike mission_time, which restarts for each step), reset by the next mission begin; the final value is held after the mission chain ends; NaN when no mission has been begun since boot or after a reset to Idle. Missing (older sender) decodes as NaN

    /// Bytes written, 0 on failure (null buffer or too small).
    size_t encode(uint8_t* out, size_t cap) const {
        constexpr size_t total = 64;
        if (out == nullptr || cap < total) return 0;
        codec::put_u32(out + 0, t_us);
        for (size_t i = 0; i < 3; ++i) codec::put_f32(out + 4 + i * 4, setpoint_pos[i]);
        for (size_t i = 0; i < 3; ++i) codec::put_f32(out + 16 + i * 4, setpoint_vel[i]);
        codec::put_i32(out + 28, static_cast<int32_t>(codec::fixedEncode(mission_time, 0.001, -2147483647LL, 2147483647LL, -2147483648LL)));
        codec::put_u8(out + 32, index);
        codec::put_u8(out + 33, phase);
        for (size_t i = 0; i < 4; ++i) codec::put_f32(out + 34 + i * 4, setpoint_q[i]);
        codec::put_u8(out + 50, mission_mode);
        codec::put_u8(out + 51, waypoint);
        codec::put_f32(out + 52, flip_start_altitude);
        codec::put_f32(out + 56, stop_altitude);
        codec::put_i32(out + 60, static_cast<int32_t>(codec::fixedEncode(mission_elapsed, 0.001, -2147483647LL, 2147483647LL, -2147483648LL)));
        return total;
    }

    /// False if the payload is shorter than kMinSize (or a tail is too long). Longer payloads are accepted (extra
    /// bytes ignored); optional fields missing from shorter payloads get their default/NaN.
    bool decode(const uint8_t* in, size_t len) {
        if (in == nullptr || len < kMinSize) return false;
        Mission t;
        t.t_us = codec::get_u32(in + 0);
        for (size_t i = 0; i < 3; ++i) t.setpoint_pos[i] = codec::get_f32(in + 4 + i * 4);
        for (size_t i = 0; i < 3; ++i) t.setpoint_vel[i] = codec::get_f32(in + 16 + i * 4);
        t.mission_time = static_cast<float>(codec::fixedDecode(codec::get_i32(in + 28), 0.001, -2147483648LL));
        t.index = codec::get_u8(in + 32);
        t.phase = codec::get_u8(in + 33);
        if (len >= 50) {
            for (size_t i = 0; i < 4; ++i) t.setpoint_q[i] = codec::get_f32(in + 34 + i * 4);
        } else {
            for (size_t i = 0; i < 4; ++i) t.setpoint_q[i] = std::numeric_limits<float>::quiet_NaN();
        }
        if (len >= 51) {
            t.mission_mode = codec::get_u8(in + 50);
        } else {
            t.mission_mode = 0;
        }
        if (len >= 52) {
            t.waypoint = codec::get_u8(in + 51);
        } else {
            t.waypoint = 0;
        }
        if (len >= 56) {
            t.flip_start_altitude = codec::get_f32(in + 52);
        } else {
            t.flip_start_altitude = std::numeric_limits<float>::quiet_NaN();
        }
        if (len >= 60) {
            t.stop_altitude = codec::get_f32(in + 56);
        } else {
            t.stop_altitude = std::numeric_limits<float>::quiet_NaN();
        }
        if (len >= 64) {
            t.mission_elapsed = static_cast<float>(codec::fixedDecode(codec::get_i32(in + 60), 0.001, -2147483648LL));
        } else {
            t.mission_elapsed = std::numeric_limits<float>::quiet_NaN();
        }
        *this = t;
        return true;
    }

    /// Calls v.scalar/array/chars/tail(name, member) for every field (used by tests and tooling).
    template <class V>
    void visit(V& v) {
        v.scalar("t_us", t_us);
        v.array("setpoint_pos", setpoint_pos);
        v.array("setpoint_vel", setpoint_vel);
        v.scalar("mission_time", mission_time);
        v.scalar("index", index);
        v.scalar("phase", phase);
        v.array("setpoint_q", setpoint_q);
        v.scalar("mission_mode", mission_mode);
        v.scalar("waypoint", waypoint);
        v.scalar("flip_start_altitude", flip_start_altitude);
        v.scalar("stop_altitude", stop_altitude);
        v.scalar("mission_elapsed", mission_elapsed);
        (void)v;
    }
};

/// GS-control design, USB only (no air cost; replaces RC_APPLIED at 0x84): the CMD_STATE fields as the vehicle applies them (last accepted frame of the latched session), the transition detectors' safe-seen bits, ages, the latched session and the reject counters. For bench debugging of the command path.
struct CmdApplied {
    static constexpr uint8_t kPort = 0x84;
    static constexpr bool kIsHeartbeat = false;
    static constexpr uint8_t kQos = 3; // telemetry (Control 0, Link 1, Event 2, Telemetry 3)
    static constexpr bool kLatest = true;
    static constexpr bool kAirEligible = false;
    static constexpr uint16_t kAirRateHz = 0;
    static constexpr uint16_t kUsbRateHz = 10;
    static constexpr size_t kMaxSize = 26;
    static constexpr size_t kMinSize = 26;
    static constexpr uint8_t kFlagsPocketLive = uint8_t(1u << 0);
    static constexpr uint8_t kFlagsInputVirtual = uint8_t(1u << 1);
    static constexpr uint8_t kSafeSeenGo = uint8_t(1u << 0);
    static constexpr uint8_t kSafeSeenScReal = uint8_t(1u << 1);
    static constexpr uint8_t kSafeSeenSdEnable = uint8_t(1u << 2);
    static constexpr uint8_t kSafeSeenSePress = uint8_t(1u << 3);

    uint32_t t_us = {}; // [us] 
    CmdGo go = {}; // last accepted go (NOT_GO if none yet)
    uint8_t profile = {}; // last accepted profile 0, 1, 2
    CmdVehicleMode vehicle_mode = {}; // last accepted vehicle_mode field (not the applied mode)
    CmdMotors motors = {}; // last accepted motors field
    CmdButton reset_button = {}; // last accepted reset_button field
    CmdFailsafe failsafe = {}; // last accepted failsafe field
    uint8_t flags = {}; // the information flags of the last accepted CMD_STATE (POCKET_LIVE = CMD_STATE flags bit 1, INPUT_VIRTUAL = bit 2); reported, never acted on. Bits 2..7 reserved
    uint8_t safe_seen = {}; // each unsafe-direction detector's 'safe value seen' bit (set: an edge may be reported). SC_REAL: vehicle_mode REAL seen (or SIMULATION seen for the reverse edge, as the mapper defines it). Bits 4..7 reserved
    uint32_t session = {}; // full latched session id, 0 = none
    float age = {}; // [s] age of the last accepted CMD_STATE (either link), invalid (NaN) = none
    float usb_age = {}; // [s] age of the last accepted or duplicate copy of the latched session on the USB link, invalid (NaN) = none
    float uart_age = {}; // [s] same for the UART link
    uint8_t rejects[4] = {}; // wrapping reject counters per reason: [0] bad length or field out of range, [1] source (src not 0), [2] foreign session, [3] stale or duplicate sequence

    /// Bytes written, 0 on failure (null buffer or too small).
    size_t encode(uint8_t* out, size_t cap) const {
        constexpr size_t total = 26;
        if (out == nullptr || cap < total) return 0;
        codec::put_u32(out + 0, t_us);
        codec::put_u8(out + 4, static_cast<uint8_t>(go));
        codec::put_u8(out + 5, profile);
        codec::put_u8(out + 6, static_cast<uint8_t>(vehicle_mode));
        codec::put_u8(out + 7, static_cast<uint8_t>(motors));
        codec::put_u8(out + 8, static_cast<uint8_t>(reset_button));
        codec::put_u8(out + 9, static_cast<uint8_t>(failsafe));
        codec::put_u8(out + 10, flags);
        codec::put_u8(out + 11, safe_seen);
        codec::put_u32(out + 12, session);
        codec::put_u16(out + 16, static_cast<uint16_t>(codec::fixedEncode(age, 0.001, 0LL, 65534LL, 65535LL)));
        codec::put_u16(out + 18, static_cast<uint16_t>(codec::fixedEncode(usb_age, 0.001, 0LL, 65534LL, 65535LL)));
        codec::put_u16(out + 20, static_cast<uint16_t>(codec::fixedEncode(uart_age, 0.001, 0LL, 65534LL, 65535LL)));
        for (size_t i = 0; i < 4; ++i) codec::put_u8(out + 22 + i * 1, rejects[i]);
        return total;
    }

    /// False if the payload is shorter than kMinSize (or a tail is too long). Longer payloads are accepted (extra
    /// bytes ignored); optional fields missing from shorter payloads get their default/NaN.
    bool decode(const uint8_t* in, size_t len) {
        if (in == nullptr || len < kMinSize) return false;
        CmdApplied t;
        t.t_us = codec::get_u32(in + 0);
        t.go = static_cast<CmdGo>(codec::get_u8(in + 4));
        t.profile = codec::get_u8(in + 5);
        t.vehicle_mode = static_cast<CmdVehicleMode>(codec::get_u8(in + 6));
        t.motors = static_cast<CmdMotors>(codec::get_u8(in + 7));
        t.reset_button = static_cast<CmdButton>(codec::get_u8(in + 8));
        t.failsafe = static_cast<CmdFailsafe>(codec::get_u8(in + 9));
        t.flags = codec::get_u8(in + 10);
        t.safe_seen = codec::get_u8(in + 11);
        t.session = codec::get_u32(in + 12);
        t.age = static_cast<float>(codec::fixedDecode(codec::get_u16(in + 16), 0.001, 65535LL));
        t.usb_age = static_cast<float>(codec::fixedDecode(codec::get_u16(in + 18), 0.001, 65535LL));
        t.uart_age = static_cast<float>(codec::fixedDecode(codec::get_u16(in + 20), 0.001, 65535LL));
        for (size_t i = 0; i < 4; ++i) t.rejects[i] = codec::get_u8(in + 22 + i * 1);
        *this = t;
        return true;
    }

    /// Calls v.scalar/array/chars/tail(name, member) for every field (used by tests and tooling).
    template <class V>
    void visit(V& v) {
        v.scalar("t_us", t_us);
        v.scalar("go", go);
        v.scalar("profile", profile);
        v.scalar("vehicle_mode", vehicle_mode);
        v.scalar("motors", motors);
        v.scalar("reset_button", reset_button);
        v.scalar("failsafe", failsafe);
        v.scalar("flags", flags);
        v.scalar("safe_seen", safe_seen);
        v.scalar("session", session);
        v.scalar("age", age);
        v.scalar("usb_age", usb_age);
        v.scalar("uart_age", uart_age);
        v.array("rejects", rejects);
        (void)v;
    }
};

/// GNSS solution at 10 Hz (the latest receiver solution; 5 Hz before 2026-11-21). Latitude and longitude in radians as f64 (full receiver resolution, 1e-7 degree is about 1 cm), altitude in metres as the receiver driver reports it (the u-blox height above the WGS-84 ellipsoid, not above mean sea level: it differs from the barometric altitude by the geoid separation, so compare changes or values relative to the pad, not absolute values). Used to verify the barometric/estimated altitude during descent; AIR_GNSS is the compact version for the radio.
struct Gnss {
    static constexpr uint8_t kPort = 0x83;
    static constexpr bool kIsHeartbeat = false;
    static constexpr uint8_t kQos = 3; // telemetry (Control 0, Link 1, Event 2, Telemetry 3)
    static constexpr bool kLatest = true;
    static constexpr bool kAirEligible = false;
    static constexpr uint16_t kAirRateHz = 0;
    static constexpr uint16_t kUsbRateHz = 10;
    static constexpr size_t kMaxSize = 50;
    static constexpr size_t kMinSize = 50;

    uint32_t t_us = {}; // [us] 
    double latitude = {}; // [rad] 
    double longitude = {}; // [rad] 
    float altitude = {}; // [m] 
    float vel[3] = {}; // [m/s] NWU
    uint8_t satellites = {};
    uint8_t fix_type = {};
    float h_acc = {}; // [m] 
    float v_acc = {}; // [m] 
    float s_acc = {}; // [m/s] 

    /// Bytes written, 0 on failure (null buffer or too small).
    size_t encode(uint8_t* out, size_t cap) const {
        constexpr size_t total = 50;
        if (out == nullptr || cap < total) return 0;
        codec::put_u32(out + 0, t_us);
        codec::put_f64(out + 4, latitude);
        codec::put_f64(out + 12, longitude);
        codec::put_f32(out + 20, altitude);
        for (size_t i = 0; i < 3; ++i) codec::put_f32(out + 24 + i * 4, vel[i]);
        codec::put_u8(out + 36, satellites);
        codec::put_u8(out + 37, fix_type);
        codec::put_f32(out + 38, h_acc);
        codec::put_f32(out + 42, v_acc);
        codec::put_f32(out + 46, s_acc);
        return total;
    }

    /// False if the payload is shorter than kMinSize (or a tail is too long). Longer payloads are accepted (extra
    /// bytes ignored); optional fields missing from shorter payloads get their default/NaN.
    bool decode(const uint8_t* in, size_t len) {
        if (in == nullptr || len < kMinSize) return false;
        Gnss t;
        t.t_us = codec::get_u32(in + 0);
        t.latitude = codec::get_f64(in + 4);
        t.longitude = codec::get_f64(in + 12);
        t.altitude = codec::get_f32(in + 20);
        for (size_t i = 0; i < 3; ++i) t.vel[i] = codec::get_f32(in + 24 + i * 4);
        t.satellites = codec::get_u8(in + 36);
        t.fix_type = codec::get_u8(in + 37);
        t.h_acc = codec::get_f32(in + 38);
        t.v_acc = codec::get_f32(in + 42);
        t.s_acc = codec::get_f32(in + 46);
        *this = t;
        return true;
    }

    /// Calls v.scalar/array/chars/tail(name, member) for every field (used by tests and tooling).
    template <class V>
    void visit(V& v) {
        v.scalar("t_us", t_us);
        v.scalar("latitude", latitude);
        v.scalar("longitude", longitude);
        v.scalar("altitude", altitude);
        v.array("vel", vel);
        v.scalar("satellites", satellites);
        v.scalar("fix_type", fix_type);
        v.scalar("h_acc", h_acc);
        v.scalar("v_acc", v_acc);
        v.scalar("s_acc", s_acc);
        (void)v;
    }
};

